create extension if not exists pgcrypto;
create table if not exists public.members(id uuid primary key references auth.users(id) on delete cascade,full_name text not null,phone text,referral_code text unique,referred_by uuid references public.members(id),role text not null default 'member' check(role in('member','admin')),created_at timestamptz not null default now());
create table if not exists public.deposits(id uuid primary key default gen_random_uuid(),member_id uuid not null references public.members(id) on delete cascade,amount numeric(14,2) not null check(amount>0),status text not null default 'pending' check(status in('pending','approved','rejected')),payment_reference text,deposited_at timestamptz not null default now(),approved_at timestamptz);
create table if not exists public.investments(id uuid primary key default gen_random_uuid(),investment_name text not null,description text,amount_invested numeric(14,2) not null check(amount_invested>0),purchase_date date not null default current_date,status text not null default 'active' check(status in('planned','active','sold','cancelled')),created_at timestamptz not null default now());
create table if not exists public.stock(id uuid primary key default gen_random_uuid(),investment_id uuid references public.investments(id) on delete set null,item_name text not null,quantity numeric(14,2) not null check(quantity>0),purchase_cost numeric(14,2) not null check(purchase_cost>=0),expected_sale_value numeric(14,2),remaining_quantity numeric(14,2),created_at timestamptz not null default now());
create table if not exists public.sales(id uuid primary key default gen_random_uuid(),stock_id uuid references public.stock(id) on delete set null,quantity numeric(14,2) not null check(quantity>0),sale_amount numeric(14,2) not null check(sale_amount>=0),expenses numeric(14,2) not null default 0 check(expenses>=0),sale_date date not null default current_date,notes text,created_at timestamptz not null default now());
create table if not exists public.profit_distributions(id uuid primary key default gen_random_uuid(),member_id uuid not null references public.members(id) on delete cascade,investment_id uuid references public.investments(id) on delete set null,contribution_base numeric(14,2) not null default 0,profit_amount numeric(14,2) not null default 0,distributed_at timestamptz not null default now());
create table if not exists public.withdrawals(id uuid primary key default gen_random_uuid(),member_id uuid not null references public.members(id) on delete cascade,amount numeric(14,2) not null check(amount>0),status text not null default 'pending' check(status in('pending','approved','rejected','paid')),payment_reference text,requested_at timestamptz not null default now(),processed_at timestamptz);
create table if not exists public.referrals(id uuid primary key default gen_random_uuid(),referrer_id uuid not null references public.members(id) on delete cascade,referred_member_id uuid not null references public.members(id) on delete cascade,status text not null default 'registered' check(status in('registered','qualified')),created_at timestamptz not null default now(),unique(referrer_id,referred_member_id));
create table if not exists public.transactions(id uuid primary key default gen_random_uuid(),member_id uuid references public.members(id) on delete set null,transaction_type text not null check(transaction_type in('deposit','withdrawal','profit','investment','sale','referral')),amount numeric(14,2) not null default 0,reference_id uuid,description text,created_at timestamptz not null default now());
create index if not exists idx_deposits_member on public.deposits(member_id);create index if not exists idx_withdrawals_member on public.withdrawals(member_id);create index if not exists idx_profit_member on public.profit_distributions(member_id);create index if not exists idx_transactions_member on public.transactions(member_id);create index if not exists idx_referrals_referrer on public.referrals(referrer_id);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.members(id,full_name,referral_code) values(new.id,coalesce(new.raw_user_meta_data->>'full_name','Member'),upper(substr(replace(new.id::text,'-',''),1,8))) on conflict(id) do nothing; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
alter table public.members enable row level security;alter table public.deposits enable row level security;alter table public.investments enable row level security;alter table public.stock enable row level security;alter table public.sales enable row level security;alter table public.profit_distributions enable row level security;alter table public.withdrawals enable row level security;alter table public.referrals enable row level security;alter table public.transactions enable row level security;
create policy "own member profile" on public.members for select to authenticated using(auth.uid()=id);create policy "update own member profile" on public.members for update to authenticated using(auth.uid()=id);
create policy "own deposits" on public.deposits for select to authenticated using(auth.uid()=member_id);create policy "create own deposits" on public.deposits for insert to authenticated with check(auth.uid()=member_id);
create policy "own withdrawals" on public.withdrawals for select to authenticated using(auth.uid()=member_id);create policy "create own withdrawals" on public.withdrawals for insert to authenticated with check(auth.uid()=member_id);
create policy "own profits" on public.profit_distributions for select to authenticated using(auth.uid()=member_id);create policy "own referrals" on public.referrals for select to authenticated using(auth.uid()=referrer_id or auth.uid()=referred_member_id);create policy "own transactions" on public.transactions for select to authenticated using(auth.uid()=member_id);
